// Vapi sends: { message: { type: 'tool-calls', toolCallList: [...], call: {...} } }
const msg = $input.first().json.body.message;
const toolCall = msg.toolCallList[0];
const args = typeof toolCall.function.arguments === 'string'
  ? JSON.parse(toolCall.function.arguments)
  : toolCall.function.arguments;

return [{
  json: {
    tool: toolCall.function.name,
    tool_call_id: toolCall.id,
    caller_id: (msg.call && msg.call.customer && msg.call.customer.number) || '',
    ...args
  }
}];

// Business settings: edit for each client
const TZ_OFFSET = '-05:00';           // business time zone offset
const WINDOWS = [[8, 10], [10, 12], [12, 14], [14, 16], [16, 18]];

const req = $('Parse tool call').first().json;
const pad = n => String(n).padStart(2, '0');
const at = h => new Date(req.date + 'T' + pad(h) + ':00:00' + TZ_OFFSET).getTime();

const busy = $input.all()
  .map(i => i.json)
  .filter(e => e.start && e.end)
  .map(e => [
    new Date(e.start.dateTime || e.start.date).getTime(),
    new Date(e.end.dateTime || e.end.date).getTime()
  ]);

const now = Date.now();
const open = WINDOWS.filter(([s, e]) =>
  at(s) > now && !busy.some(([bs, be]) => bs < at(e) && be > at(s))
);

const label = h => (h % 12 || 12) + (h < 12 ? ' AM' : ' PM');
const result = open.length
  ? 'Open arrival windows on ' + req.date + ': ' +
    open.map(([s, e]) => label(s) + ' to ' + label(e) + ' (window_start ' + pad(s) + ':00)').join(', ') + '.'
  : 'No open windows on ' + req.date + '. Offer to check the next day.';

return [{ json: { tool_call_id: req.tool_call_id, result } }];

const TZ_OFFSET = '-05:00';
const WINDOW_HOURS = 2;

const r = $input.first().json;
const [h, m] = r.window_start.split(':').map(Number);
const pad = n => String(n).padStart(2, '0');
const label = hr => (hr % 12 || 12) + (hr < 12 ? ' AM' : ' PM');

return [{
  json: {
    job_id: 'JOB-' + Date.now().toString(36).toUpperCase(),
    tool_call_id: r.tool_call_id,
    booked_at: new Date().toISOString(),
    customer_name: r.customer_name,
    phone: r.phone,
    caller_id: r.caller_id,
    address: r.address,
    zip: r.zip,
    service_type: r.service_type,
    issue: r.issue,
    urgency: r.urgency,
    date: r.date,
    window: label(h) + ' to ' + label(h + WINDOW_HOURS),
    start: r.date + 'T' + pad(h) + ':' + pad(m || 0) + ':00' + TZ_OFFSET,
    end: r.date + 'T' + pad(h + WINDOW_HOURS) + ':' + pad(m || 0) + ':00' + TZ_OFFSET,
    status: 'booked'
  }
}];
